// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address nextOwner) public {
        vm.assume(newOwner != address(0));
        vm.assume(nextOwner != address(0));
        vm.assume(newOwner != nextOwner);
        c.setOwner(newOwner);
        vm.prank(newOwner);
        bool ok;
        try c.setOwner(nextOwner) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
